        frame.save(c, S3, 0x100);
        c.g[S2][0] = c.g[A3][0];
        frame.save(c, S4, 0xf0);
        c.g[S3][0] = c.g[A2][0];
        frame.save(c, S0, 0x130);
        c.g[S4][0] = c.g[A0][0];
        frame.save_ra(c, 0xe0);
        let cursor = frame.at(c, BRP_CURSOR);
        c.sw(cursor, c.g[A1][0]);
        c.g[A0][0] = c.g[S1][0];
