        Addr(frame.at(c, 0xcc)).sw(c, s0);
        c.g[A0][0] = c.g[SP][0];
        let s1 = c.g[S1][0];
        Addr(frame.at(c, 0xd0)).sw(c, s1);
        Callee {
            addr: 0x003b_4fc0,
            f: ee::s13::f_003b4fc0,
        }
        .call(c, 0x003c_6000)?;
        frame.restore(c, S0, 0x100);
        c.g[V0][0] = 0;
        frame.restore(c, S1, 0xf0);
        frame.restore_ra(c, 0xe0);
