                    c.g[V0][0] = sx((c.g[V0][0] as u32) << 16);
                    c.g[V0][0] = sx((c.g[V0][0] as u32).wrapping_sub(c.g[A1][0] as u32));
                    c.div(0, 2, 3);
                    c.g[V0][0] = c.lo[0];
                    c.sw((c.g[A2][0] as u32).wrapping_add(0x3c), c.g[V0][0]);
