                        c.g[V1][0] = c.lhu((c.g[T5][0] as u32).wrapping_add(0x8));
                        c.sh((c.g[T0][0] as u32).wrapping_add(0x20), c.g[V1][0]);
                        c.g[V0][0] = c.lhu((c.g[T5][0] as u32).wrapping_add(0xc));
                        c.sh((c.g[T0][0] as u32).wrapping_add(0x22), c.g[V0][0]);
