                            c.g[V0][0] = c.g[V0][0] & c.g[T9][0];
                            c.g[V0][0] = c.g[V0][0] | c.g[T2][0];
                            c.g[V0][0] = c.g[V0][0] & c.g[T1][0];
                            c.g[V0][0] = c.g[V0][0] | c.g[T7][0];
                            c.sw(c.g[A0][0] as u32, c.g[V0][0]);
                            c.sb((c.g[A0][0] as u32).wrapping_add(0x3), c.g[T6][0]);
