    pub(crate) fn seed_setup(c: &mut Cpu, seed: u32) -> Rng {
        let mut r = Rng(0x3bc5_8800 ^ seed as u64);
        scramble(c, &mut r);
        c.pc = 0x003b_c588;
        fill(c, &mut r, RANDOM_SEED_TABLE, 6);
        fill(c, &mut r, RANDOM_STATE, 6);
        r
    }

