    #[test]
    fn spch_seed_random_matches() {
        check(
            ee::s14::f_003db790__generated,
            spch_seed_random,
            200,
            &|c, seed| {
                let mut r = Rng(0x7a92_0001 ^ seed as u64);
                scramble(c, &mut r);
                c.pc = 0x003d_b790;
                c.g[GP][0] = sx(GAME_GP);
                c.g[A0][0] = match seed % 4 {
                    0 => 0,
                    1 => sx(r.next_u32() & 0xffff),
                    _ => sx(r.next_u32()),
                };
            },
        );
    }

