    /// Fills `len` bytes at `base` with random words.
    pub(crate) fn fill_2(c: &mut Cpu, r: &mut Rng, base: u32, len: u32) {
        for k in (0..len).step_by(4) {
            c.bus.write32(base + k, r.next_u32());
        }
    }

